<script>
document.addEventListener('DOMContentLoaded', function () {
    var base = <?= json_encode(rtrim(site_url('admin/users'), '/'), JSON_UNESCAPED_SLASHES) ?>;
    var editModal = document.getElementById('editUserModal');
    editModal.addEventListener('show.bs.modal', function (event) {
        var button = event.relatedTarget;
        document.getElementById('editUserForm').action = base + '/' + button.dataset.employeeId + '/update';
        document.getElementById('editUserTitle').textContent = 'Edit ' + (button.dataset.name || 'account');
        document.getElementById('editUserId').textContent = 'Employee #' + button.dataset.employeeId;
        document.getElementById('editName').value = button.dataset.name || '';
        document.getElementById('editEmail').value = button.dataset.email || '';
        document.getElementById('editDepartment').value = button.dataset.department || '';
        document.getElementById('editPosition').value = button.dataset.position || '';
        document.getElementById('editRole').value = button.dataset.role || 'admin';
    });
    var resetModal = document.getElementById('resetPasswordModal');
    resetModal.addEventListener('show.bs.modal', function (event) {
        var button = event.relatedTarget;
        document.getElementById('resetPasswordForm').action = base + '/' + button.dataset.employeeId + '/reset-password';
        document.getElementById('resetPasswordUser').textContent = (button.dataset.name || 'Account') + ' · Employee #' + button.dataset.employeeId;
        document.getElementById('resetPassword').value = '';
        document.getElementById('resetPasswordConfirm').value = '';
    });
});
</script>
